package io.github.borderarea01.znote;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;

/** Local submission recovery, separate from server download history. */
public class CapturePendingActivity extends Activity {
    private final Handler handler=new Handler(Looper.getMainLooper());private LinearLayout rows;private String last="";private final Runnable refresh=new Runnable(){public void run(){render();handler.postDelayed(this,1000);}};
    @Override public void onCreate(Bundle state){super.onCreate(state);NativeAppearance.load(this);NativeAppearance.window(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);int gap=Math.round(20*getResources().getDisplayMetrics().density);root.setPadding(gap,gap*2,gap,gap);root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(gap+bars.left,gap+bars.top,gap+bars.right,gap+bars.bottom);}return insets;});root.setBackgroundColor(NativeUi.BG);TextView title=new TextView(this);title.setText("待提交任务");title.setTextSize(24);title.setTextColor(NativeUi.TEXT);root.addView(title);Button back=NativeUi.button(this,"返回",this::finish);root.addView(back);ScrollView scroll=new ScrollView(this);rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);scroll.addView(rows);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);CaptureOutbox.resume(this);}
    private void action(Runnable run){try{run.run();last="";render();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}
    private void render(){JSONArray entries=CaptureOutbox.list(this);if(last.equals(entries.toString()))return;last=entries.toString();rows.removeAllViews();if(entries.length()==0){TextView empty=new TextView(this);empty.setText("暂无待提交任务");empty.setTextColor(NativeUi.MUTED);rows.addView(empty);return;}for(int i=0;i<entries.length();i++){JSONObject row=entries.optJSONObject(i);String id=row.optString("id"),state=row.optString("state");LinearLayout card=NativeUi.card(rows,"failed".equals(state)?"提交未完成":"accepted".equals(state)?"服务器已接收":"正在后台提交");TextView text=new TextView(this);text.setText(row.optString("text"));text.setTextColor(NativeUi.TEXT);text.setTextIsSelectable(true);text.setMaxLines(4);card.addView(text);CaptureCatalogue.Snapshot cache=CaptureCatalogue.read(this);int at=cache.ids.indexOf(row.optString("collection"));TextView target=new TextView(this);target.setText("保存到："+(at>=0?cache.names.get(at):"上次选择的知识库"));target.setTextColor(NativeUi.MUTED);card.addView(target);TextView message=new TextView(this);message.setText(row.optString("error"));message.setTextColor(NativeUi.MUTED);card.addView(message);if("failed".equals(state)){card.addView(NativeUi.button(this,"重试提交",()->action(()->{try{CaptureOutbox.retry(this,id);}catch(Exception e){throw new RuntimeException(e.getMessage());}})));if(!PixivSession.work(CaptureAssistService.link(row.optString("text"))).isEmpty())card.addView(NativeUi.button(this,"Pixiv 登录",()->startActivity(new Intent(this,PixivLoginActivity.class))));card.addView(NativeUi.button(this,"打开 ZNote",()->startActivity(new Intent(this,MainActivity.class))));card.addView(NativeUi.button(this,"移除任务",()->new AlertDialog.Builder(this).setTitle("移除手机待提交记录？").setMessage("只移除手机记录；已经到达服务器的任务仍会继续。").setNegativeButton("取消",null).setPositiveButton("移除",(d,w)->action(()->{try{CaptureOutbox.remove(this,id);}catch(Exception e){throw new RuntimeException(e.getMessage());}})).show()));}}}
    @Override protected void onResume(){super.onResume();handler.post(refresh);}
    @Override protected void onPause(){handler.removeCallbacksAndMessages(null);super.onPause();}
}
